ruleSearch.bookList:
.grid tr!0
<js>
result.toArray().slice(0, 3).map(el => {
	var url = String(el.select('a:eq(0)').attr('href')).replace(/^\//, baseUrl.match(/(.+?\/\/[^\/]+\/)/)[1]);
	var J = org.jsoup.Jsoup.parse(java.ajax(url));
	var o = selector => String(J.select(selector).text());
	var og = selector => String(J.select('[property="og:' + selector + '"]').attr('content'));
	return {
		name: og('novel:book_name').replace(/(全文|小说|免费阅读|最新章节).*|[(（].*[）)]/g, ''),
		author: og('novel:author'),
		kind: og('novel:category') + ',' + og('novel:status').replace(/中|已/, ''),
		latest: og('novel:lastest_chapter_name').replace(/^(正文|VIP章节|最新章节)?(\s+|_)|[\(（【].*[求更谢乐发推].*/g, '') + ' • ' + og('novel:update_time').replace(/(T|\s).*/, ' ').replace(/\//g, '-'),
		intro: og('description').replace(/.*(观看小说|简介)[:：]|各位书友.*/g, '').replace(/\s+/g, ''),
		cover: og('image'),
		url: url,
	};
}); 
</js>

.searchlist li<js>
result
   .toArray()
   .slice(0, 3)
   .map(function (el){
    var url = String(el.select('a').eq(0).attr('href')).replace(
      /^\/([^\/])/,
      baseUrl.match(/(.+\/\/.+?\/)/)[1] + '$1'
    );
    var J = org.jsoup.Jsoup.parse(String(java.ajax(url)));
    var og = (selector) =>
      String(J.select('[property="og:' + selector + '"]').attr('content'));

    return {
      name: og('novel:book_name').replace(/(全文|小说|免费|最新章节).*|（.*）/,''),
      author: og('novel:author'),
      kind: og('novel:category') + ',' + og('novel:status').replace(/中|已/,''),
      latest: J.select('.bookcover p').eq(4).text(),
      cover: og('image'),
      wordCount: parseInt(J.select('.num').eq(0).text().replace('字','')/10000)+'万',  
      intro: og('description').replace(/.*简介：|各位书友.*/,'').replace(/\s+/g,''),
      url: url,
    };
  });
</js>

